// Konkuk University, Seoul Campus (건국대학교 서울캠퍼스, 서울 광진구). Data is generated by scripts/campuses/konkuk/build-package.mjs
// from the pilot (pilot/konkuk-seoul, round 3): the destructible buildings of active-models.json (상허기념도서관·신공학관·새천년관·
// 박물관(구 서북학회회관) detailed, the rest generic; the museum is destructible by the user's decision 2026-10-19), the pilot's
// destructible:false models as protected (건국대학교병원, 도정궁 경원당, KU동물암센터; shield, never damaged), a baked ground with the pilot's ground shader (the SKKU port
// src/campuses/skku/ground-look.js; the pilot's final-materials.js is the same shader as dankook's), the 일감호 (water sheet with
// landscape/landscape.mjs's ripple shader ported below to world units, revetment, 와우도, 홍예교, 청심대), 노천극장, 상허문 and the
// non-destructible context (광진·자양, 2·7호선 viaducts, 어린이대공원 woods) fading into the haze. Local only until the user approves
// (registry public: false).
import { WORLD_UNITS_PER_METER, GEO_ORIGIN, KU_PLACEMENTS, KU_BUILDING_BASE, KU_HEIGHT_GRIDS, KU_HEIGHT_RANGE_M, KU_ENV_IDS, KU_ENV_MANIFEST_IDS, KU_LOOK, KU_ZONES, KU_DISPLAY, KU_PROVENANCE } from './data.js';
import { KU_FOOTPRINTS } from './footprints.js';
import { KU_PROTECTED } from './protected.js';
import { createSkkuGroundLook } from '../skku/ground-look.js';

const MODEL_IDS = Object.freeze(KU_PLACEMENTS.map(p => p.id));
const asset = file => new URL(`../../../assets/campuses/konkuk/${file}`, import.meta.url).href;
const HAZE = KU_DISPLAY.haze || '#dde5e8', FADE = KU_DISPLAY.fade;

// 일감호 water: pilot landscape/landscape.mjs onBeforeCompile (faint world-space ripple normal so the sun glint is not a flat plate,
// slightly darker towards the middle of the lake). The pilot works in metres; the game scene is metres x worldUnitsPerMeter, so world
// positions are scaled back to metres first. Only the material baked with extras.konkukWater (lake.gltf 'water') is touched.
function createLakeWater(W) {
  const unit = (1 / W).toFixed(6);
  return material => {
    if (!material.userData?.konkukWater) return false;
    material.metalness = 0; material.roughness = .22;
    material.onBeforeCompile = sh => {
      sh.vertexShader = sh.vertexShader.replace('#include <common>', '#include <common>\nvarying vec3 vWp;')
        .replace('#include <worldpos_vertex>', `#include <worldpos_vertex>\nvWp = (modelMatrix * vec4(transformed, 1.0)).xyz * ${unit};`);
      sh.fragmentShader = sh.fragmentShader.replace('#include <common>', '#include <common>\nvarying vec3 vWp;')
        .replace('#include <normal_fragment_maps>', '#include <normal_fragment_maps>\n{ vec2 q = vWp.xz; vec3 rp = vec3(sin(q.x*.9+q.y*.4)*.5+sin(q.x*.23-q.y*1.3)*.35, 0., cos(q.y*.8-q.x*.3)*.5+cos(q.x*1.7+q.y*.2)*.25)*.035;\n normal = normalize(normal + (viewMatrix * vec4(rp, 0.)).xyz); }')
        .replace('#include <color_fragment>', '#include <color_fragment>\n{ float dd = clamp(length(vWp.xz - vec2(-6., -24.)) / 160., 0., 1.); diffuseColor.rgb *= mix(.82, 1.06, dd); }');
    };
    material.customProgramCacheKey = () => 'konkuk-lake1';
    material.needsUpdate = true;
    return true;
  };
}
const groundLook = createSkkuGroundLook(KU_LOOK, KU_ZONES);
const materialHook = (THREE, ctx) => { const ground = groundLook(THREE, ctx), water = createLakeWater(ctx.worldUnitsPerMeter ?? WORLD_UNITS_PER_METER);
  return material => water(material) || ground(material); };

export const KONKUK = Object.freeze({
  id: 'konkuk',
  meta: Object.freeze({ school: '건국대학교', campus: '서울캠퍼스', short: '건국대', modelNoun: '건국대' }),
  geo: Object.freeze({ origin: GEO_ORIGIN, worldUnitsPerMeter: WORLD_UNITS_PER_METER }),
  placements: KU_PLACEMENTS,
  approvedCount: KU_PLACEMENTS.length,
  additionalCount: 0,
  coreIds: Object.freeze(['museum', 'library', 'newEngineering', 'millennium'].filter(id => MODEL_IDS.includes(id))),
  startBuildingId: 'museum',
  // Start: from the south shore (레이크홀 side) across 일감호 to the north - 와우도 in the foreground, 홍예교 on the right by 학생회관,
  // 청심대 on the far shore and 상허기념관 (박물관, the old 서북학회회관) on the north-west hill above the water.
  // Box = E -70..100 m, N -85..195 m (world units: metres x 0.5, z = -N); azimuth .3 = camera to the south-south-east of the box.
  view: Object.freeze({ startFrame: Object.freeze({ min: Object.freeze([-35, -1, -97.5]), max: Object.freeze([50, 14, 42.5]), azimuth: .3 }) }),
  models: Object.freeze({
    manifests: Object.freeze([
      Object.freeze({ url: asset('manifest.json'), expectedIds: MODEL_IDS }),
      Object.freeze({ url: asset('environment.json'), expectedIds: KU_ENV_MANIFEST_IDS }),
    ]),
    proceduralIds: Object.freeze([]),
    createProceduralSource: () => { throw new Error('No procedural buildings in this campus'); },
    enhanceFacade: () => ({ stats: {}, dispose() {} }),
  }),
  terrain: Object.freeze({ heightGrids: KU_HEIGHT_GRIDS, buildingBase: KU_BUILDING_BASE,
    source: 'Relative terrain estimate (Copernicus GLO-30, building-filled, canopy lowered by an estimate, 일감호 water datum 0 + floor / photo level evidence, pilot/konkuk-seoul); not a survey' }),
  environment: Object.freeze({ provenance: KU_PROVENANCE, sourceNote: 'OSM ground surfaces and surroundings (© OpenStreetMap contributors, ODbL); heights, planting, the lake edge and the place models estimated' }),
  ground: Object.freeze({
    baked: Object.freeze({ envIds: KU_ENV_IDS, castShadow: Object.freeze([]), materialHook,
      fade: Object.freeze({ centre_m: Object.freeze(FADE ? [...FADE.centreEN] : [8.5, 100.2]), near_m: FADE?.r0_m ?? 560, far_m: FADE?.r1_m ?? 1300, ...(FADE?.linearShare ? { linear: FADE.linearShare } : {}), colour: HAZE }), playMargin_m: 30,
      source: 'pilot/konkuk-seoul preview ground + 일감호 / 노천극장 / 상허문 + context, baked' }),
  }),
  // Protected (pilot destructible:false: 건국대학교병원, 도정궁 경원당 hanok heritage, KU동물암센터): never destructible; weapons meet the
  // protective shield (src/protected-buildings.js); own manifest, models packed with the campus cache (shared textures).
  protected: Object.freeze({
    manifestURL: asset('protected/manifest.json'),
    models: KU_PROTECTED,
  }),
  // Hazard tape around every destructible building only (src/engine/hazard-tape.js): none on the protected models or the context.
  hazardTape: Object.freeze({ footprints: KU_FOOTPRINTS }),
  scene: Object.freeze({
    background: HAZE, fog: Object.freeze({ color: HAZE, near: 760, far: 2400 }),
    hemisphere: Object.freeze({ sky: '#eef2f4', ground: '#7d8a78', intensity: 1.3 }),
    // preview.js sun direction (-300, 280, 200) -> (40, 0, 20), halved into world units
    sun: Object.freeze({ color: '#fff4e2', intensity: 2.9, position: Object.freeze([-170, 140, 90]), shadowSpan: 260 }),
    floor: Object.freeze({ color: '#c9cbc8', hidden: true, y: KU_HEIGHT_RANGE_M[0] * WORLD_UNITS_PER_METER - .3 }),
  }),
});
export default KONKUK;
